INSERT INTO temp_additional_reviews VALUES
('54500700-0000-4000-9000-000000000301', '54500700-0000-4000-8000-000000000038', 'p-tourapi-1620863', '양금석가옥', '남원 춘향골 정취가 물씬 풍기는 멋진 한옥입니다. 정자랑 연못 뷰가 한 폭의 그림 같아요.', '한적', 1, '["남원여행", "연못뷰", "풍경맛집"]'::jsonb, 33.291311, 126.628597, '2026-10-12T14:32:29Z'::timestamptz),
('54500700-0000-4000-9000-000000000302', '54500700-0000-4000-8000-000000000042', 'p-tourapi-1908555', '지리산한옥마을', '대숲 바람 소리 사각사각 들리고 처마 밑에 앉아있으니 신선놀음이 따로 없네요. 강력 추천!', '한적', 1, '["대숲바람", "고즈넉", "힐링"]'::jsonb, 35.418226, 127.625727, '2026-10-12T15:08:29Z'::timestamptz),
('54500700-0000-4000-9000-000000000303', '54500700-0000-4000-8000-000000000044', 'p-tourapi-250460', '남원몽심재', '남원몽심재 다녀왔어요! 대숲 바람 소리 사각사각 들리고 처마 밑에 앉아있으니 신선놀음이 따로 없네요. 강력 추천!', '한적', 1, '["대숲바람", "고즈넉", "힐링"]'::jsonb, 35.337994, 127.374746, '2026-10-12T10:42:29Z'::timestamptz),
('54500700-0000-4000-9000-000000000304', '54500700-0000-4000-8000-000000000046', 'p-tourapi-2528155', '남원예촌', '남원예촌 다녀왔어요! 남원 춘향골 정취가 물씬 풍기는 멋진 한옥입니다. 정자랑 연못 뷰가 한 폭의 그림 같아요.', '한적', 1, '["남원여행", "연못뷰", "풍경맛집", "온마루"]'::jsonb, 35.404443, 127.379394, '2026-10-12T09:57:29Z'::timestamptz),
('54500700-0000-4000-9000-000000000305', '54500700-0000-4000-8000-000000000036', 'p-tourapi-2613382', '수곡당', '수곡당 다녀왔어요! 전통 체험 프로그램도 잘 되어 있어서 재밌게 즐기고 갑니다. 기념품도 하나 건졌어요!', '북적', 1, '["전통체험", "데이트", "주말나들이"]'::jsonb, 35.405340, 127.381974, '2026-10-12T11:56:29Z'::timestamptz),
('54500700-0000-4000-9000-000000000306', '54500700-0000-4000-8000-000000000046', 'p-tourapi-2660381', '매월당', '남원 춘향골 정취가 물씬 풍기는 멋진 한옥입니다. 정자랑 연못 뷰가 한 폭의 그림 같아요.', '한적', 1, '["남원여행", "연못뷰", "풍경맛집"]'::jsonb, 35.348864, 127.272895, '2026-10-12T15:51:29Z'::timestamptz),
('54500700-0000-4000-9000-000000000307', '54500700-0000-4000-8000-000000000053', 'p-tourapi-2751703', '달팽이', '달팽이 다녀왔어요! 대숲 바람 소리 사각사각 들리고 처마 밑에 앉아있으니 신선놀음이 따로 없네요. 강력 추천!', '한적', 2, '["대숲바람", "고즈넉", "힐링", "온마루"]'::jsonb, 35.413979, 127.616603, '2026-10-12T15:04:29Z'::timestamptz),
('54500700-0000-4000-9000-000000000308', '54500700-0000-4000-8000-000000000047', 'p-tourapi-2961964', '하정사색', '대숲 바람 소리 사각사각 들리고 처마 밑에 앉아있으니 신선놀음이 따로 없네요. 강력 추천!', '한적', 1, '["대숲바람", "고즈넉", "힐링"]'::jsonb, 35.408399, 127.382242, '2026-10-12T15:39:29Z'::timestamptz),
('54500700-0000-4000-9000-000000000309', '54500700-0000-4000-8000-000000000042', 'p-tourapi-3040204', '함파우소리체험관', '남원 춘향골 정취가 물씬 풍기는 멋진 한옥입니다. 정자랑 연못 뷰가 한 폭의 그림 같아요.', '한적', 1, '["남원여행", "연못뷰", "풍경맛집", "온마루"]'::jsonb, 35.398096, 127.384307, '2026-10-12T16:29:29Z'::timestamptz),
('54500700-0000-4000-9000-000000000310', '54500700-0000-4000-8000-000000000050', 'p-tourapi-126375', '진도 운림산방', '진도 운림산방 다녀왔어요! 전통 체험 프로그램도 잘 되어 있어서 재밌게 즐기고 갑니다. 기념품도 하나 건졌어요!', '북적', 1, '["전통체험", "데이트", "주말나들이", "온마루"]'::jsonb, 34.466413, 126.308364, '2026-10-12T10:30:29Z'::timestamptz),
('54500700-0000-4000-9000-000000000311', '54500700-0000-4000-8000-000000000053', 'p-tourapi-127520', '서귀포 김정희 유배지', '서귀포 김정희 유배지 다녀왔어요! 제주 돌담이랑 전통 초가/한옥 감성이 섞여서 이국적이면서도 독특해요! 귤나무랑 조화 대박.', '한적', 1, '["제주돌담", "이색한옥", "사진맛집", "온마루"]'::jsonb, 33.249935, 126.278322, '2026-10-12T14:49:29Z'::timestamptz),
('54500700-0000-4000-9000-000000000312', '54500700-0000-4000-8000-000000000045', 'p-tourapi-1620863', '양금석가옥', '양금석가옥 다녀왔어요! 제주도에서 한옥이라니 색다르고 너무 좋았어요. 마당에 핀 들꽃들도 너무 예쁨!', '북적', 2, '["제주핫플", "데이트", "인생샷"]'::jsonb, 33.291311, 126.628597, '2026-10-12T15:47:29Z'::timestamptz),
